+export function trimSession(session, startFraction, endFraction) {
+  const startIdx = Math.floor(session.turns.length * startFraction);
+  const endIdx = Math.ceil(session.turns.length * endFraction);
+  return { ...session, turns: session.turns.slice(startIdx, endIdx) };
+}
